class ConfirmChangeNowSendView extends ConsumerStatefulWidget {
  const ConfirmChangeNowSendView({
    super.key,
    required this.txData,
    required this.walletId,
    this.routeOnSuccessName = WalletView.routeName,
    required this.trade,
    this.shouldSendPublicFiroFunds,
    this.fromDesktopStep4 = false,
  });

  static const String routeName = "/confirmChangeNowSend";

  final TxData txData;
  final String walletId;
  final String routeOnSuccessName;
  final Trade trade;
  final bool? shouldSendPublicFiroFunds;
  final bool fromDesktopStep4;

  @override
  ConsumerState<ConfirmChangeNowSendView> createState() =>
      _ConfirmChangeNowSendViewState();
}

class _ConfirmChangeNowSendViewState
    extends ConsumerState<ConfirmChangeNowSendView> {
  late final String walletId;
  late final String routeOnSuccessName;
  late final Trade trade;

  final isDesktop = Util.isDesktop;
  bool _sending = false;
  bool _quoteChanged = false;
  bool get _isRosen => trade.exchangeName == RosenExchange.exchangeName;
  bool get _isRosenToken =>
      _isRosen && trade.payInCurrency.toLowerCase() == "rsfiro";

  String _totalAmount() {
    final formatter = ref.watch(
      pAmountFormatter(ref.watch(pWalletCoin(walletId))),
    );
    final fee = widget.txData.fee!;
    if (_isRosenToken) {
      return "${trade.payInAmount} ${trade.payInCurrency} + ${formatter.format(fee)}";
    }
    final amount =
        widget.txData.amountWithoutChange ??
        widget.txData.amountSparkWithoutChange!;
    return formatter.format(amount + fee);
  }

  Future<void> _attemptSend(BuildContext context) async {
    if (_sending || _quoteChanged) return;
    if (_isRosen &&
        (ref
                .read(tradesServiceProvider)
                .get(trade.tradeId)
                ?.payInTxid
                .isNotEmpty ??
            false)) {
      return;
    }
    _sending = true;
    final wallet = ref.read(pWallets).getWallet(walletId);
    final coin = wallet.info.coin;

    final sendProgressController = ProgressAndSuccessController();
    var isSendingDialogOpen = false;

    void closeSendingDialog() {
      if (!context.mounted || !isSendingDialogOpen) {
        return;
      }
      final rootNavigator = Navigator.of(context, rootNavigator: true);
      if (rootNavigator.canPop()) {
        rootNavigator.pop();
      }
      isSendingDialogOpen = false;
    }

    isSendingDialogOpen = true;
    unawaited(
      showDialog<void>(
        context: context,
        useRootNavigator: true,
        useSafeArea: false,
        barrierDismissible: false,
        builder: (context) {
          return SendingTransactionDialog(
            coin: coin,
            controller: sendProgressController,
          );
        },
      ).whenComplete(() => isSendingDialogOpen = false),
    );

    final time = Future<dynamic>.delayed(const Duration(milliseconds: 2500));

    String? broadcastTxid;
    late String txid;
    Future<TxData> txidFuture;

    final String note = widget.txData.note ?? "";

    try {
      if (_isRosen) {
        txidFuture = RosenFunding.confirmSend(
          wallet: wallet,
          trade: trade,
          txData: widget.txData,
        );
      } else if (wallet is FiroWallet &&
          widget.shouldSendPublicFiroFunds == false) {
        txidFuture = wallet.confirmSendSpark(txData: widget.txData);
      } else {
        txidFuture = wallet.confirmSend(txData: widget.txData);
      }

      unawaited(wallet.refresh());

      final sent = await txidFuture;
      txid = sent.txid!;
      broadcastTxid = txid;
      if (_isRosen) {
        await ref
            .read(tradesServiceProvider)
            .edit(
              trade: trade.copyWith(
                payInTxid: txid,
                status: "Confirming",
                updatedAt: DateTime.now(),
              ),
              shouldNotifyListeners: true,
            );
      }
      await time;

      sendProgressController.triggerSuccess?.call();
      await Future<void>.delayed(const Duration(seconds: 5));

      // save note
      await ref
          .read(mainDBProvider)
          .putTransactionNote(
            TransactionNote(walletId: walletId, txid: txid, value: note),
          );

      await ref
          .read(tradeSentFromStackLookupProvider)
          .save(
            tradeWalletLookup: TradeWalletLookup(
              uuid: const Uuid().v1(),
              txid: txid,
              tradeId: trade.tradeId,
              walletIds: [walletId],
            ),
          );

      // pop back to wallet
      if (context.mounted) {
        closeSendingDialog();
        if (Util.isDesktop) {
          // one day we'll do routing right
          Navigator.of(context, rootNavigator: true).pop();
          if (widget.fromDesktopStep4) {
            Navigator.of(context, rootNavigator: true).pop();
          }
        }

        Navigator.of(context).popUntil(ModalRoute.withName(routeOnSuccessName));
      }
    } catch (e, s) {
      if (broadcastTxid == null) _sending = false;
      Logging.instance.e(
        "Broadcast transaction failed: ",
        error: e,
        stackTrace: s,
      );

      // pop sending dialog
      closeSendingDialog();

      if (broadcastTxid == null &&
          e is ExchangeException &&
          e.type == ExchangeExceptionType.quoteChanged) {
        if (!mounted) return;
        setState(() => _quoteChanged = true);
        await _refreshQuote();
        return;
      }

      await showDialog<dynamic>(
        context: context,
        useSafeArea: false,
        barrierDismissible: true,
        builder: (context) {
          return StackDialog(
            title: broadcastTxid == null
                ? "Broadcast transaction failed"
                : "Transaction sent",
            message: broadcastTxid == null
                ? e.toString()
                : "Transaction $broadcastTxid was sent, but saving its details failed: $e. Do not send again.",
            rightButton: TextButton(
              style: Theme.of(context)
                  .extension<StackColors>()!
                  .getSecondaryEnabledButtonStyle(context),
              child: Text(
                "Ok",
                style: STextStyles.button(context).copyWith(
                  color: Theme.of(
                    context,
                  ).extension<StackColors>()!.buttonTextSecondary,
                ),
              ),
              onPressed: () {
                Navigator.of(context).pop();
              },
            ),
          );
        },
      );
    }
  }

  Future<void> _refreshQuote() async {
    if (await showRosenQuoteChangedDialog(context) && mounted) {
      // Discard the prepared transaction; SendFrom rebuilds it for fresh review.
      Navigator.of(context).pop(true);
    }
  }

  Future<void> _confirmSend() async {
    if (_quoteChanged) {
      await _refreshQuote();
      return;
    }
    final dynamic unlocked;

    final coin = ref.read(pWalletCoin(walletId));

    if (Util.isDesktop) {
      unlocked = await showDialog<bool?>(
        context: context,
        builder: (context) => DesktopDialog(
          maxWidth: 580,
          maxHeight: double.infinity,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Row(
                mainAxisAlignment: MainAxisAlignment.end,
                children: [DesktopDialogCloseButton()],
              ),
              Padding(
                padding: const EdgeInsets.only(left: 32, right: 32, bottom: 32),
                child: DesktopAuthSend(coin: coin),
              ),
            ],
          ),
        ),
      );
    } else {
      unlocked = await Navigator.push(
        context,
        RouteGenerator.getRoute(
          shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
          builder: (_) => const LockscreenView(
            showBackButton: true,
            popOnSuccess: true,
            routeOnSuccessArguments: true,
            routeOnSuccess: "",
            biometricsCancelButtonString: "CANCEL",
            biometricsLocalizedReason: "Authenticate to send transaction",
            biometricsAuthenticationTitle: "Confirm Transaction",
          ),
          settings: const RouteSettings(name: "/confirmsendlockscreen"),
        ),
      );
    }

    if (unlocked is bool && mounted) {
      if (unlocked) {
        await _attemptSend(context);
      } else {
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.warning,
            message: "Invalid passphrase",
            context: context,
          ),
        );
      }
    }
  }

